#[derive(Debug, Parser)]
#[command(
    name = "xlsx-jsx",
    version,
    about = "Compile JSX/TSX workbooks to XLSX and reverse supported XLSX files"
)]
struct Cli {
    #[command(subcommand)]
    command: Command,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// Compile an executable JSX/TSX workbook.
    Build {
        input: PathBuf,
        #[arg(short, long)]
        output: PathBuf,
        #[arg(long)]
        data: Option<PathBuf>,
        #[arg(long)]
        force: bool,
    },
    /// Validate JSX/TSX without writing an XLSX file.
    Validate {
        input: PathBuf,
        #[arg(long)]
        data: Option<PathBuf>,
    },
    /// Reverse a supported XLSX file to JSX.
    Reverse {
        input: PathBuf,
        #[arg(short, long)]
        output: Option<PathBuf>,
        #[arg(long)]
        force: bool,
    },
    /// Print the machine-readable feature specification.
    Spec {
        #[arg(long, default_value = "markdown")]
        format: String,
    },
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> ExitCode {
    match run(Cli::parse()).await {
        Ok(Some(path)) => {
            println!("{}", path.display());
            ExitCode::SUCCESS
        }
        Ok(None) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("{}", error.render_diagnostic());
            ExitCode::FAILURE
        }
    }
}

async fn run(cli: Cli) -> xlsx_jsx::Result<Option<PathBuf>> {
    match cli.command {
        Command::Spec { format } => {
            let spec = match format.as_str() {
                "markdown" => include_str!("../docs/spec.md"),
                "json" => include_str!("../spec/ir-v1.schema.json"),
                _ => return Err(Error::Input(format!("unknown spec format `{format}`"))),
            };
            print!("{spec}");
            Ok(None)
        }
        Command::Validate { input, data } => {
            evaluate(&input, data.as_deref()).await?;
            println!("valid");
            Ok(None)
        }
        Command::Build {
            input,
            output,
            data,
            force,
        } => {
            require_extension(&output, "xlsx")?;
            ensure_output(&output, force)?;
            let ir = evaluate(&input, data.as_deref()).await?;
            compile(&ir, &output)?;
            Ok(Some(output))
        }
        Command::Reverse {
            input,
            output,
            force,
        } => {
            require_extension(&input, "xlsx")?;
            let output = output.unwrap_or_else(|| input.with_extension("tsx"));
            ensure_output(&output, force)?;
            let source = reverse(&input)?;
            std::fs::write(&output, source).map_err(|source| Error::Output {
                path: output.clone(),
                source,
            })?;
            Ok(Some(output))
        }
    }
}

async fn evaluate(
    input: &std::path::Path,
    data: Option<&std::path::Path>,
) -> xlsx_jsx::Result<IrEnvelope> {
    let value = data
        .map(|path| {
            std::fs::read_to_string(path).map_err(|source| Error::Resource {
                path: path.to_path_buf(),
                source,
            })
        })
        .transpose()?
        .map(|text| {
            serde_json::from_str::<Value>(&text)
                .map_err(|error| Error::Input(format!("invalid JSON data: {error}")))
        })
        .transpose()?;
    evaluate_entry(input, value.as_ref()).await
}

fn ensure_output(output: &std::path::Path, force: bool) -> xlsx_jsx::Result<()> {
    if output.exists() && !force {
        return Err(Error::Input(format!(
            "output {} already exists",
            output.display()
        )));
    }
    Ok(())
}

fn require_extension(path: &std::path::Path, expected: &str) -> xlsx_jsx::Result<()> {
    if !path
        .extension()
        .is_some_and(|extension| extension.eq_ignore_ascii_case(expected))
    {
        return Err(Error::Input(format!(
            "expected a .{expected} path, got {}",
            path.display()
        )));
    }
    Ok(())
}

#[allow(clippy::too_many_lines)] // Worksheet serialization keeps row and column ordering together.
fn compile(ir: &IrEnvelope, path: &std::path::Path) -> xlsx_jsx::Result<()> {
    let mut workbook = Workbook::new();
    let mut properties = DocProperties::new();
    if let Some(value) = ir.workbook.props.get("title").and_then(Value::as_str) {
        properties = properties.set_title(value);
    }
    if let Some(value) = ir.workbook.props.get("subject").and_then(Value::as_str) {
        properties = properties.set_subject(value);
    }
    if let Some(value) = ir.workbook.props.get("author").and_then(Value::as_str) {
        properties = properties.set_author(value);
    }
    if let Some(value) = ir.workbook.props.get("keywords").and_then(Value::as_str) {
        properties = properties.set_keywords(value);
    }
    if let Some(value) = ir.workbook.props.get("description").and_then(Value::as_str) {
        properties = properties.set_comment(value);
    }
    workbook.set_properties(&properties);
    let mut local_defined_names = Vec::new();
    for value in &ir.workbook.children {
        let node: Node = serde_json::from_value(value.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if node.r#type == "DefinedName" {
            let name = node.props["name"].as_str().expect("validated name");
            let formula = node.props["formula"].as_str().expect("validated formula");
            workbook
                .define_name(name, formula.strip_prefix('=').unwrap_or(formula))
                .map_err(|error| {
                    Error::Compile(format!(
                        "DefinedName `{name}`: {error}; use a valid Excel name and formula"
                    ))
                })?;
        }
    }
    for sheet_value in &ir.workbook.children {
        let sheet: Node = serde_json::from_value(sheet_value.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if sheet.r#type == "DefinedName" {
            continue;
        }
        let name = sheet
            .props
            .get("name")
            .and_then(Value::as_str)
            .ok_or_else(|| Error::Compile("worksheet missing name".into()))?;
        for child_value in &sheet.children {
            let child: Node = serde_json::from_value(child_value.clone())
                .map_err(|error| Error::Compile(error.to_string()))?;
            if child.r#type == "DefinedName" {
                local_defined_names.push((
                    name.to_owned(),
                    child.props["name"]
                        .as_str()
                        .expect("validated name")
                        .to_owned(),
                    child.props["formula"]
                        .as_str()
                        .expect("validated formula")
                        .strip_prefix('=')
                        .unwrap_or(child.props["formula"].as_str().expect("validated formula"))
                        .to_owned(),
                ));
            }
        }
        let worksheet = workbook.add_worksheet();
        worksheet
            .set_name(name)
            .map_err(|error| Error::Compile(error.to_string()))?;
        if sheet.props.get("active").and_then(Value::as_bool) == Some(true) {
            worksheet.set_active(true);
        }
        if let Some(selected) = sheet.props.get("selected").and_then(Value::as_bool) {
            worksheet.set_selected(selected);
        }
        if sheet.props.get("firstTab").and_then(Value::as_bool) == Some(true) {
            worksheet.set_first_tab(true);
        }
        apply_worksheet_visibility(worksheet, &sheet)?;
        apply_worksheet_tab_color(worksheet, &sheet)?;
        apply_default_row_height(worksheet, &sheet)?;
        apply_hide_unused_rows(worksheet, &sheet)?;
        apply_show_gridlines(worksheet, &sheet)?;
        apply_worksheet_reading_direction(worksheet, &sheet);
        apply_print_gridlines(worksheet, &sheet)?;
        apply_worksheet_view(worksheet, &sheet);
        apply_worksheet_zoom(worksheet, &sheet)?;
        apply_worksheet_page_breaks(worksheet, &sheet)?;
        apply_worksheet_page_margins(worksheet, &sheet)?;
        apply_worksheet_print_settings(worksheet, &sheet)?;
        apply_worksheet_header_footer(worksheet, &sheet);
        apply_worksheet_protection(worksheet, &sheet);
        apply_outline_summary_directions(worksheet, &sheet);
        apply_freeze_panes(worksheet, &sheet)?;
        apply_worksheet_selection(worksheet, &sheet)?;
        apply_auto_filter(worksheet, &sheet)?;
        let mut row_index = 0_usize;
        let mut row_outline = Vec::new();
        let mut column_outline = BTreeMap::new();
        let mut merged_ranges: Vec<(u32, u16, u32, u16)> = Vec::new();
        let mut tables = Vec::new();
        for child_value in &sheet.children {
            let child: Node = serde_json::from_value(child_value.clone())
                .map_err(|error| Error::Compile(error.to_string()))?;
            if child.r#type == "DefinedName" {
                continue;
            }
            if child.r#type == "Note" {
                compile_note(worksheet, &child)?;
                continue;
            }
            if child.r#type == "Chart" {
                compile_chart(worksheet, &child)?;
                continue;
            }
            if child.r#type == "Image" {
                compile_image(worksheet, &child)?;
                continue;
            }
            if child.r#type == "Column" {
                let min = u16::try_from(child.props["min"].as_u64().unwrap_or(1))
                    .map_err(|error| Error::Compile(format!("invalid Column.min: {error}")))?;
                let max = u16::try_from(child.props["max"].as_u64().unwrap_or(u64::from(min)))
                    .map_err(|error| Error::Compile(format!("invalid Column.max: {error}")))?;
                let width = child.props.get("widthPixels").and_then(Value::as_u64);
                let width_pixels = width.map(u32::try_from).transpose().map_err(|error| {
                    Error::Compile(format!("invalid Column.widthPixels: {error}"))
                })?;
                let hidden = child.props.get("hidden").and_then(Value::as_bool) == Some(true);
                let outline_level = child
                    .props
                    .get("outlineLevel")
                    .and_then(Value::as_u64)
                    .unwrap_or_default();
                for column_number in min..=max {
                    let col = column_number - 1;
                    if let Some(width_pixels) = width_pixels {
                        worksheet
                            .set_column_width_pixels(col, width_pixels)
                            .map_err(|error| Error::Compile(error.to_string()))?;
                    }
                    if hidden {
                        worksheet
                            .set_column_hidden(col)
                            .map_err(|error| Error::Compile(error.to_string()))?;
                    }
                    if has_format_properties(&child) {
                        let format = build_cell_format(&child)?;
                        worksheet
                            .set_column_format(col, &format)
                            .map_err(|error| Error::Compile(error.to_string()))?;
                    }
                    column_outline.insert(
                        col,
                        ColumnProperties {
                            width_pixels,
                            hidden,
                            outline_level: u8::try_from(outline_level).unwrap_or_default(),
                            collapsed: child.props.get("collapsed").and_then(Value::as_bool)
                                == Some(true),
                            style_index: None,
                        },
                    );
                }
                continue;
            }
            if child.r#type == "DataValidation" {
                compile_data_validation(worksheet, &child)?;
                continue;
            }
            if child.r#type == "ConditionalFormat" {
                compile_conditional_format(worksheet, &child)?;
                continue;
            }
            if child.r#type == "IgnoreError" {
                compile_ignored_error(worksheet, &child)?;
                continue;
            }
            if child.r#type == "Table" {
                tables.push(child);
                continue;
            }
            compile_row(worksheet, &child, row_index, &mut merged_ranges)?;
            row_outline.push(OutlineProperties {
                hidden: child.props.get("hidden").and_then(Value::as_bool) == Some(true),
                level: child
                    .props
                    .get("outlineLevel")
                    .and_then(Value::as_u64)
                    .and_then(|level| u8::try_from(level).ok())
                    .unwrap_or_default(),
                collapsed: child.props.get("collapsed").and_then(Value::as_bool) == Some(true),
            });
            row_index += 1;
        }
        for table in &tables {
            compile_table(worksheet, &sheet, table)?;
        }
        let row_outline = row_outline
            .into_iter()
            .enumerate()
            .map(|(row, properties)| {
                let row = u32::try_from(row)
                    .map_err(|error| Error::Compile(format!("invalid row index: {error}")))?;
                Ok((row, properties))
            })
            .collect::<xlsx_jsx::Result<BTreeMap<_, _>>>()?;
        let row_groups = collapsed_outline_ranges(&row_outline, "row").map_err(Error::Compile)?;
        for &(first_row, last_row) in &row_groups {
            worksheet
                .group_rows_collapsed(first_row, last_row)
                .map_err(|error| Error::Compile(error.to_string()))?;
        }
        for (&row, properties) in &row_outline {
            let collapsed_depth = row_groups
                .iter()
                .filter(|(first, last)| *first <= row && row <= *last)
                .count();
            let expanded_depth = usize::from(properties.level)
                .checked_sub(collapsed_depth)
                .ok_or_else(|| Error::Compile(format!(
                    "row {} belongs to more collapsed groups than its outline level; raise outlineLevel or simplify the group nesting",
                    row + 1
                )))?;
            for _ in 0..expanded_depth {
                worksheet
                    .group_rows(row, row)
                    .map_err(|error| Error::Compile(error.to_string()))?;
            }
        }
        let column_outline_for_groups = column_outline
            .iter()
            .map(|(&column, properties)| {
                (
                    u32::from(column),
                    OutlineProperties {
                        hidden: properties.hidden,
                        level: properties.outline_level,
                        collapsed: properties.collapsed,
                    },
                )
            })
            .collect::<BTreeMap<_, _>>();
        let column_groups = collapsed_outline_ranges(&column_outline_for_groups, "column")
            .map_err(Error::Compile)?;
        for &(first_column, last_column) in &column_groups {
            let first_column = u16::try_from(first_column)
                .map_err(|error| Error::Compile(format!("invalid collapsed column: {error}")))?;
            let last_column = u16::try_from(last_column)
                .map_err(|error| Error::Compile(format!("invalid collapsed column: {error}")))?;
            worksheet
                .group_columns_collapsed(first_column, last_column)
                .map_err(|error| Error::Compile(error.to_string()))?;
        }
        for (&column, properties) in &column_outline {
            let coordinate = u32::from(column);
            let collapsed_depth = column_groups
                .iter()
                .filter(|(first, last)| *first <= coordinate && coordinate <= *last)
                .count();
            let expanded_depth = usize::from(properties.outline_level)
                .checked_sub(collapsed_depth)
                .ok_or_else(|| Error::Compile(format!(
                    "column {} belongs to more collapsed groups than its outline level; raise outlineLevel or simplify the group nesting",
                    coordinate + 1
                )))?;
            for _ in 0..expanded_depth {
                worksheet
                    .group_columns(column, column)
                    .map_err(|error| Error::Compile(error.to_string()))?;
            }
        }
    }
    for (sheet_name, name, formula) in local_defined_names {
        let quoted_sheet = sheet_name.replace('\'', "''");
        workbook
            .define_name(format!("'{quoted_sheet}'!{name}"), &formula)
            .map_err(|error| Error::Compile(format!("worksheet-local DefinedName `{name}` on `{sheet_name}`: {error}; use a valid Excel name and formula")))?;
    }
    workbook.save(path).map_err(|error| Error::Output {
        path: path.to_path_buf(),
        source: std::io::Error::other(error.to_string()),
    })?;
    let x14_icon_normalization = collect_x14_icon_normalization_targets(ir)?;
    if !x14_icon_normalization.is_empty() {
        normalize_x14_icon_rules(path, &x14_icon_normalization)?;
    }
    Ok(())
}

#[derive(Default)]
struct X14IconRuleNormalization {
    greater_than_thresholds: Vec<usize>,
    reverse: bool,
    show_icons_only: bool,
    stop_if_true: bool,
}

fn collect_x14_icon_normalization_targets(
    ir: &IrEnvelope,
) -> xlsx_jsx::Result<HashMap<String, HashMap<u32, X14IconRuleNormalization>>> {
    let mut targets = HashMap::new();
    let mut worksheet_part = 0_u32;
    for value in &ir.workbook.children {
        let sheet: Node = serde_json::from_value(value.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if sheet.r#type != "Worksheet" {
            continue;
        }
        worksheet_part += 1;
        let mut priority = 0_u32;
        for child_value in &sheet.children {
            let child: Node = serde_json::from_value(child_value.clone())
                .map_err(|error| Error::Compile(error.to_string()))?;
            if child.r#type != "ConditionalFormat"
                || child.props.get("type").and_then(Value::as_str) != Some("iconSet")
            {
                continue;
            }
            let icons = child.props.get("icons").and_then(Value::as_array);
            let icon_type = child
                .props
                .get("iconType")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let x14_only_icon_types = ["threeStars", "threeTriangles", "fiveBoxes"];
            let has_custom_icons = icons.is_some_and(|icons| {
                icons.iter().any(|icon| {
                    icon.as_object().is_some_and(|icon| {
                        ["iconType", "iconIndex", "noIcon"]
                            .iter()
                            .any(|key| icon.contains_key(*key))
                    })
                })
            });
            let is_x14_only = x14_only_icon_types.contains(&icon_type) || has_custom_icons;
            if !is_x14_only {
                continue;
            }
            priority += 1;
            let greater_than_indices = icons
                .into_iter()
                .flat_map(|icons| icons.iter())
                .enumerate()
                .filter_map(|(index, icon)| {
                    icon.as_object()
                        .and_then(|icon| icon.get("greaterThan"))
                        .and_then(Value::as_bool)
                        .filter(|greater_than| *greater_than)
                        .map(|_| index)
                })
                .collect::<Vec<_>>();
            let normalization = X14IconRuleNormalization {
                greater_than_thresholds: greater_than_indices,
                reverse: child.props.get("reverse").and_then(Value::as_bool) == Some(true),
                show_icons_only: child.props.get("showIconsOnly").and_then(Value::as_bool)
                    == Some(true),
                stop_if_true: child.props.get("stopIfTrue").and_then(Value::as_bool) == Some(true),
            };
            if !normalization.greater_than_thresholds.is_empty()
                || normalization.reverse
                || normalization.show_icons_only
                || normalization.stop_if_true
            {
                targets
                    .entry(format!("xl/worksheets/sheet{worksheet_part}.xml"))
                    .or_insert_with(HashMap::new)
                    .insert(priority, normalization);
            }
        }
    }
    Ok(targets)
}

fn normalize_x14_icon_rules(
    path: &std::path::Path,
    targets_by_part: &HashMap<String, HashMap<u32, X14IconRuleNormalization>>,
) -> xlsx_jsx::Result<()> {
    let parent = path.parent().unwrap_or_else(|| std::path::Path::new("."));
    let file_name = path
        .file_name()
        .and_then(std::ffi::OsStr::to_str)
        .unwrap_or("workbook.xlsx");
    let (temporary_path, temporary_file) = (0_u32..100)
        .find_map(|attempt| {
            let candidate = parent.join(format!(
                ".{file_name}.xlsx-jsx-{}-{attempt}.tmp",
                std::process::id()
            ));
            std::fs::OpenOptions::new()
                .write(true)
                .read(true)
                .create_new(true)
                .open(&candidate)
                .ok()
                .map(|file| (candidate, file))
        })
        .ok_or_else(|| Error::Compile("cannot create a temporary XLSX normalization file beside the output; close conflicting processes or remove stale `.xlsx-jsx-*.tmp` files".into()))?;

    let rewrite_result = rewrite_xlsx_with_x14_icon_rules(path, temporary_file, targets_by_part);
    if let Err(error) = rewrite_result {
        let _ = std::fs::remove_file(&temporary_path);
        return Err(error);
    }

    #[cfg(windows)]
    std::fs::remove_file(path).map_err(|source| Error::Output {
        path: path.to_path_buf(),
        source,
    })?;
    std::fs::rename(&temporary_path, path).map_err(|source| {
        let _ = std::fs::remove_file(&temporary_path);
        Error::Output {
            path: path.to_path_buf(),
            source,
        }
    })?;
    Ok(())
}

fn rewrite_xlsx_with_x14_icon_rules(
    path: &std::path::Path,
    temporary_file: std::fs::File,
    targets_by_part: &HashMap<String, HashMap<u32, X14IconRuleNormalization>>,
) -> xlsx_jsx::Result<()> {
    let source_file = std::fs::File::open(path).map_err(|source| Error::Resource {
        path: path.to_path_buf(),
        source,
    })?;
    let mut archive = ZipArchive::new(source_file)
        .map_err(|error| Error::Compile(format!("cannot read generated XLSX package: {error}")))?;
    let mut writer = ZipWriter::new(temporary_file);
    let mut patched_parts = std::collections::HashSet::new();
    for index in 0..archive.len() {
        let mut entry = archive.by_index(index).map_err(|error| {
            Error::Compile(format!("cannot read generated XLSX entry {index}: {error}"))
        })?;
        if entry.is_dir() {
            continue;
        }
        let name = entry.name().to_owned();
        let compression = entry.compression();
        let last_modified = entry.last_modified().unwrap_or_default();
        let mut bytes = Vec::new();
        std::io::Read::read_to_end(&mut entry, &mut bytes).map_err(|error| {
            Error::Compile(format!(
                "cannot read generated XLSX entry `{name}`: {error}"
            ))
        })?;
        if let Some(targets) = targets_by_part.get(&name) {
            let xml = String::from_utf8(bytes).map_err(|error| {
                Error::Compile(format!(
                    "generated worksheet `{name}` is not UTF-8 XML: {error}"
                ))
            })?;
            bytes = patch_x14_icon_rules(&xml, targets, &name)?.into_bytes();
            patched_parts.insert(name.clone());
        }
        writer
            .start_file(
                &name,
                SimpleFileOptions::default()
                    .compression_method(compression)
                    .last_modified_time(last_modified),
            )
            .map_err(|error| {
                Error::Compile(format!(
                    "cannot rewrite generated XLSX entry `{name}`: {error}"
                ))
            })?;
        std::io::Write::write_all(&mut writer, &bytes).map_err(|error| {
            Error::Compile(format!(
                "cannot write generated XLSX entry `{name}`: {error}"
            ))
        })?;
    }
    let missing_parts = targets_by_part
        .keys()
        .filter(|part| !patched_parts.contains(*part))
        .cloned()
        .collect::<Vec<_>>();
    if !missing_parts.is_empty() {
        return Err(Error::Compile(format!(
            "generated XLSX is missing worksheet part `{}` required to preserve x14 icon thresholds; repair the workbook sheet order",
            missing_parts[0]
        )));
    }
    let output_file = writer.finish().map_err(|error| {
        Error::Compile(format!("cannot finalize normalized XLSX package: {error}"))
    })?;
    output_file.sync_all().map_err(|source| Error::Output {
        path: path.to_path_buf(),
        source,
    })?;
    drop(output_file);
    drop(archive);
    Ok(())
}

// This event loop preserves XML token order while tracking rule-local threshold indices.
#[allow(clippy::too_many_lines)]
fn patch_x14_icon_rules(
    xml: &str,
    targets_by_priority: &HashMap<u32, X14IconRuleNormalization>,
    part: &str,
) -> xlsx_jsx::Result<String> {
    let mut reader = XmlReader::from_str(xml);
    let mut writer = XmlWriter::new(Vec::with_capacity(xml.len()));
    let mut priority = None;
    let mut threshold_index = 0_usize;
    let mut patched = std::collections::HashSet::new();
    let mut patched_rules = std::collections::HashSet::new();
    loop {
        let event = reader
            .read_event()
            .map_err(|error| Error::Compile(format!("generated worksheet `{part}` has invalid XML while normalizing icon thresholds: {error}")))?;
        match event {
            Event::Start(ref start) if start.name().as_ref() == b"x14:cfRule" => {
                let raw_priority = start
                    .attributes()
                    .with_checks(false)
                    .find_map(|attribute| {
                        let attribute = attribute.ok()?;
                        (attribute.key.local_name().as_ref() == b"priority")
                            .then(|| {
                                attribute
                                    .decoded_and_normalized_value(
                                        XmlVersion::Implicit1_0,
                                        reader.decoder(),
                                    )
                                    .ok()
                            })
                            .flatten()
                    })
                    .ok_or_else(|| Error::Compile(format!(
                        "generated x14 icon rule in `{part}` has no priority; update the pinned writer adapter"
                    )))?;
                priority = Some(raw_priority.parse::<u32>().map_err(|error| {
                    Error::Compile(format!("generated x14 icon rule in `{part}` has invalid priority `{raw_priority}`: {error}"))
                })?);
                threshold_index = 0;
                if let Some(rule_priority) = priority
                    && targets_by_priority
                        .get(&rule_priority)
                        .is_some_and(|target| target.stop_if_true)
                {
                    let has_stop_if_true = start.attributes().with_checks(false).any(|attribute| {
                        attribute.is_ok_and(|attribute| {
                            attribute.key.local_name().as_ref() == b"stopIfTrue"
                        })
                    });
                    if !has_stop_if_true {
                        let mut normalized = start.to_owned();
                        normalized.push_attribute(("stopIfTrue", "1"));
                        writer
                            .write_event(Event::Start(normalized))
                            .map_err(|error| {
                                Error::Compile(format!(
                                    "cannot normalize worksheet `{part}`: {error}"
                                ))
                            })?;
                        patched_rules.insert((rule_priority, "stopIfTrue"));
                        continue;
                    }
                    patched_rules.insert((rule_priority, "stopIfTrue"));
                }
                writer.write_event(event).map_err(|error| {
                    Error::Compile(format!("cannot normalize worksheet `{part}`: {error}"))
                })?;
                continue;
            }
            Event::Start(ref start) if start.name().as_ref() == b"x14:iconSet" => {
                let Some(rule_priority) = priority else {
                    return Err(Error::Compile(format!(
                        "generated x14 iconSet in `{part}` is outside an x14 cfRule"
                    )));
                };
                let Some(target) = targets_by_priority.get(&rule_priority) else {
                    writer.write_event(event).map_err(|error| {
                        Error::Compile(format!("cannot normalize worksheet `{part}`: {error}"))
                    })?;
                    continue;
                };
                let has_reverse = start.attributes().with_checks(false).any(|attribute| {
                    attribute
                        .is_ok_and(|attribute| attribute.key.local_name().as_ref() == b"reverse")
                });
                let has_show_value = start.attributes().with_checks(false).any(|attribute| {
                    attribute
                        .is_ok_and(|attribute| attribute.key.local_name().as_ref() == b"showValue")
                });
                let mut normalized = start.to_owned();
                if target.reverse {
                    if !has_reverse {
                        normalized.push_attribute(("reverse", "1"));
                    }
                    patched_rules.insert((rule_priority, "reverse"));
                }
                if target.show_icons_only {
                    if !has_show_value {
                        normalized.push_attribute(("showValue", "0"));
                    }
                    patched_rules.insert((rule_priority, "showValue"));
                }
                writer
                    .write_event(Event::Start(normalized))
                    .map_err(|error| {
                        Error::Compile(format!("cannot normalize worksheet `{part}`: {error}"))
                    })?;
                continue;
            }
            Event::Start(ref start) if start.name().as_ref() == b"x14:cfvo" => {
                let Some(rule_priority) = priority else {
                    return Err(Error::Compile(format!(
                        "generated x14 icon threshold in `{part}` is outside an x14 cfRule"
                    )));
                };
                let current_index = threshold_index;
                threshold_index += 1;
                if targets_by_priority
                    .get(&rule_priority)
                    .is_some_and(|target| target.greater_than_thresholds.contains(&current_index))
                {
                    let has_gte = start.attributes().with_checks(false).any(|attribute| {
                        attribute
                            .is_ok_and(|attribute| attribute.key.local_name().as_ref() == b"gte")
                    });
                    if !has_gte {
                        let mut normalized = start.to_owned();
                        normalized.push_attribute(("gte", "0"));
                        writer
                            .write_event(Event::Start(normalized))
                            .map_err(|error| {
                                Error::Compile(format!(
                                    "cannot normalize worksheet `{part}`: {error}"
                                ))
                            })?;
                        patched.insert((rule_priority, current_index));
                        continue;
                    }
                    patched.insert((rule_priority, current_index));
                }
            }
            Event::Empty(ref start) if start.name().as_ref() == b"x14:cfvo" => {
                let Some(rule_priority) = priority else {
                    return Err(Error::Compile(format!(
                        "generated x14 icon threshold in `{part}` is outside an x14 cfRule"
                    )));
                };
                let current_index = threshold_index;
                threshold_index += 1;
                if targets_by_priority
                    .get(&rule_priority)
                    .is_some_and(|target| target.greater_than_thresholds.contains(&current_index))
                {
                    let has_gte = start.attributes().with_checks(false).any(|attribute| {
                        attribute
                            .is_ok_and(|attribute| attribute.key.local_name().as_ref() == b"gte")
                    });
                    if has_gte {
                        patched.insert((rule_priority, current_index));
                    } else {
                        let mut normalized = start.to_owned();
                        normalized.push_attribute(("gte", "0"));
                        writer
                            .write_event(Event::Empty(normalized))
                            .map_err(|error| {
                                Error::Compile(format!(
                                    "cannot normalize worksheet `{part}`: {error}"
                                ))
                            })?;
                        patched.insert((rule_priority, current_index));
                        continue;
                    }
                }
            }
            Event::End(ref end) if end.name().as_ref() == b"x14:cfRule" => {
                priority = None;
                threshold_index = 0;
            }
            Event::Eof => break,
            _ => {}
        }
        writer.write_event(event).map_err(|error| {
            Error::Compile(format!("cannot normalize worksheet `{part}`: {error}"))
        })?;
    }
    for (rule_priority, target) in targets_by_priority {
        for index in &target.greater_than_thresholds {
            if !patched.contains(&(*rule_priority, *index)) {
                return Err(Error::Compile(format!(
                    "pinned writer did not emit x14 icon threshold {index} for conditional-format priority {rule_priority} in `{part}`; retain the threshold order and repair the icon-set definition"
                )));
            }
        }
        for (enabled, attribute) in [
            (target.stop_if_true, "stopIfTrue"),
            (target.reverse, "reverse"),
            (target.show_icons_only, "showValue"),
        ] {
            if enabled && !patched_rules.contains(&(*rule_priority, attribute)) {
                return Err(Error::Compile(format!(
                    "pinned writer did not emit x14 icon attribute `{attribute}` for conditional-format priority {rule_priority} in `{part}`; repair the icon-set definition"
                )));
            }
        }
    }
    String::from_utf8(writer.into_inner()).map_err(|error| {
        Error::Compile(format!(
            "normalized worksheet `{part}` is not UTF-8 XML: {error}"
        ))
    })
}

fn compile_table(
    worksheet: &mut rust_xlsxwriter::Worksheet,
    sheet: &Node,
    node: &Node,
) -> xlsx_jsx::Result<()> {
    let range_text = node.props["range"]
        .as_str()
        .ok_or_else(|| Error::Compile("Table.range must be a string".into()))?;
    let range = parse_a1_range(range_text)
        .ok_or_else(|| Error::Compile(format!("invalid Table.range `{range_text}`")))?;
    let columns = build_table_columns(sheet, node, range)?;
    let name = node.props["name"]
        .as_str()
        .ok_or_else(|| Error::Compile("Table.name must be a string".into()))?;
    let mut table = Table::new().set_name(name).set_columns(&columns);
    if node.props.get("headerRow").and_then(Value::as_bool) == Some(false) {
        table = table.set_header_row(false);
    }
    if node.props.get("totalsRow").and_then(Value::as_bool) == Some(true) {
        table = table.set_total_row(true);
    }
    table = table.set_style(table_style(
        node.props
            .get("style")
            .and_then(Value::as_str)
            .unwrap_or("TableStyleMedium9"),
    )?);
    table = apply_table_accessibility_text(table, &node.props);
    for (key, setter) in [
        ("autoFilter", 0),
        ("bandedRows", 1),
        ("bandedColumns", 2),
        ("firstColumn", 3),
        ("lastColumn", 4),
    ] {
        if let Some(value) = node.props.get(key).and_then(Value::as_bool) {
            table = match setter {
                0 => table.set_autofilter(value),
                1 => table.set_banded_rows(value),
                2 => table.set_banded_columns(value),
                3 => table.set_first_column(value),
                _ => table.set_last_column(value),
            };
        }
    }
    worksheet
        .add_table(range.0, range.1, range.2, range.3, &table)
        .map_err(|error| Error::Compile(format!("cannot create Table `{name}`: {error}")))?;
    Ok(())
}

fn build_table_columns(
    sheet: &Node,
    node: &Node,
    range: (u32, u16, u32, u16),
) -> xlsx_jsx::Result<Vec<TableColumn>> {
    let has_header = node.props.get("headerRow").and_then(Value::as_bool) != Some(false);
    let row = if has_header {
        let row_value = sheet
            .children
            .iter()
            .filter(|value| value.get("type").and_then(Value::as_str) == Some("Row"))
            .nth(range.0 as usize)
            .ok_or_else(|| Error::Compile("Table header row is missing".into()))?;
        Some(
            serde_json::from_value::<Node>(row_value.clone())
                .map_err(|error| Error::Compile(error.to_string()))?,
        )
    } else {
        None
    };
    let mut columns = Vec::new();
    for col in range.1..=range.3 {
        let column_node = node.children.get(usize::from(col - range.1));
        let header_cell = if let Some(row) = &row {
            Some(
                serde_json::from_value::<Node>(row.children[usize::from(col)].clone())
                    .map_err(|error| Error::Compile(error.to_string()))?,
            )
        } else {
            None
        };
        let header = if let Some(cell) = &header_cell {
            cell.props
                .get("value")
                .and_then(Value::as_str)
                .or_else(|| cell.children.first().and_then(Value::as_str))
                .ok_or_else(|| Error::Compile("table header must be a string".into()))?
        } else {
            column_node
                .and_then(|child| child.get("props"))
                .and_then(|props| props.get("name"))
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    Error::Compile("TableColumn.name is required for a headerless table".into())
                })?
        };
        let mut column = TableColumn::new().set_header(header);
        if let Some(column_node) = column_node {
            let props = column_node.get("props").and_then(Value::as_object);
            if let Some(label) = props
                .and_then(|props| props.get("totalLabel"))
                .and_then(Value::as_str)
            {
                column = column.set_total_label(label);
            }
            if let Some(format) = props.and_then(|props| props.get("format")) {
                column = column.set_format(build_table_column_format(format)?);
            }
            if let Some(formula) = props
                .and_then(|props| props.get("formula"))
                .and_then(Value::as_str)
            {
                column = column.set_formula(formula.trim_start_matches('='));
            }
            if let Some(formula) = props
                .and_then(|props| props.get("totalFormula"))
                .and_then(Value::as_str)
            {
                column = column.set_total_function(rust_xlsxwriter::TableFunction::Custom(
                    Formula::new(formula.trim_start_matches('=')),
                ));
            } else if let Some(function) = props
                .and_then(|props| props.get("totalFunction"))
                .and_then(Value::as_str)
            {
                column = column.set_total_function(table_function(function)?);
            }
        }
        let header_format = column_node
            .and_then(|column| column.get("props"))
            .and_then(|props| props.get("headerFormat"));
        if let Some(format) = header_format {
            column = column.set_header_format(build_table_column_format(format)?);
        } else if header_cell.as_ref().is_some_and(has_format_properties) {
            let cell = header_cell.as_ref().expect("header cell exists");
            column = column.set_header_format(build_cell_format(cell)?);
        }
        columns.push(column);
    }
    Ok(columns)
}

fn apply_table_accessibility_text(
    mut table: Table,
    props: &serde_json::Map<String, Value>,
) -> Table {
    if let Some(text) = props.get("altText").and_then(Value::as_str) {
        table = table.set_alt_text(text);
    }
    if let Some(title) = props.get("altTextTitle").and_then(Value::as_str) {
        table = table.set_alt_text_title(title);
    }
    table
}

fn compile_note(
    worksheet: &mut rust_xlsxwriter::Worksheet,
    component: &Node,
) -> xlsx_jsx::Result<()> {
    let cell = component.props["cell"]
        .as_str()
        .expect("validated Note.cell");
    let (row, column) = parse_a1_cell_reference(cell).expect("validated Note.cell");
    let text = component.props["text"]
        .as_str()
        .expect("validated Note.text");
    let mut compiled_note = Note::new(text);
    if let Some(author) = component.props.get("author").and_then(Value::as_str) {
        compiled_note = compiled_note.set_author(author);
    }
    if let Some(value) = component.props.get("authorPrefix").and_then(Value::as_bool) {
        compiled_note = compiled_note.add_author_prefix(value);
    }
    if let Some(value) = component.props.get("width").and_then(Value::as_u64) {
        compiled_note =
            compiled_note.set_width(u32::try_from(value).expect("validated Note.width"));
    }
    if let Some(value) = component.props.get("height").and_then(Value::as_u64) {
        compiled_note =
            compiled_note.set_height(u32::try_from(value).expect("validated Note.height"));
    }
    if let Some(value) = component.props.get("visible").and_then(Value::as_bool) {
        compiled_note = compiled_note.set_visible(value);
    }
    if let Some(value) = component
        .props
        .get("backgroundColor")
        .and_then(Value::as_str)
    {
        compiled_note = compiled_note.set_background_color(value);
    }
    if let Some(value) = component.props.get("fontName").and_then(Value::as_str) {
        compiled_note = compiled_note.set_font_name(value);
    }
    if let Some(value) = component.props.get("fontSize").and_then(Value::as_f64) {
        compiled_note = compiled_note.set_font_size(value);
    }
    if let Some(value) = component.props.get("fontFamily").and_then(Value::as_u64) {
        compiled_note =
            compiled_note.set_font_family(u8::try_from(value).expect("validated Note.fontFamily"));
    }
    if let Some(value) = component.props.get("altText").and_then(Value::as_str) {
        compiled_note = compiled_note.set_alt_text(value);
    }
    if component.props.get("movement").and_then(Value::as_str) == Some("moveAndSizeAfter") {
        compiled_note =
            compiled_note.set_object_movement(ObjectMovement::MoveAndSizeWithCellsAfter);
    }
    worksheet
        .insert_note(row, column, &compiled_note)
        .map(|_| ())
        .map_err(|error| Error::Compile(format!("cannot add Note to {cell}: {error}")))
}

#[expect(
    clippy::too_many_lines,
    reason = "Chart compilation applies the validated chart properties and child components in one writer pass."
)]
fn compile_chart(
    worksheet: &mut rust_xlsxwriter::Worksheet,
    component: &Node,
) -> xlsx_jsx::Result<()> {
    let chart_type = chart_type_from_name(
        component.props["type"]
            .as_str()
            .expect("validated Chart.type"),
    );
    let cell = component.props["cell"]
        .as_str()
        .expect("validated Chart.cell");
    let (row, column) = parse_a1_cell_reference(cell).expect("validated Chart.cell");
    let mut chart = Chart::new(chart_type);
    if let Some(mut format) = chart_shape_format(component, "chartAreaFillColor", "chartAreaLine") {
        chart.chart_area().set_format(&mut format);
    }
    if let Some(layout) = component.props.get("plotAreaLayout") {
        let fraction = |key: &str| layout[key].as_f64().expect("validated plotAreaLayout");
        chart.plot_area().set_layout(
            &ChartLayout::new()
                .set_offset(fraction("x"), fraction("y"))
                .set_dimensions(fraction("width"), fraction("height")),
        );
    }
    if let Some(layout) = component.props.get("legendLayout") {
        let fraction = |key: &str| layout[key].as_f64().expect("validated legendLayout");
        chart.legend().set_layout(
            &ChartLayout::new()
                .set_offset(fraction("x"), fraction("y"))
                .set_dimensions(fraction("width"), fraction("height")),
        );
    }
    if let Some(mut format) = chart_shape_format(component, "legendFillColor", "legendLine") {
        chart.legend().set_format(&mut format);
    }
    configure_chart_legend_font(&mut chart, component);
    if let Some(mut format) = chart_shape_format(component, "plotAreaFillColor", "plotAreaLine") {
        chart.plot_area().set_format(&mut format);
    }
    if component.props.get("type").and_then(Value::as_str) == Some("stock") {
        chart.set_high_low_lines(true);
        if component
            .children
            .iter()
            .filter(|value| value.get("type").and_then(Value::as_str) == Some("Series"))
            .count()
            == 4
        {
            chart.set_up_down_bars(true);
            if let Some(mut format) = chart_shape_format(component, "upBarColor", "upBarLine") {
                chart.set_up_bar_format(&mut format);
            }
            if let Some(mut format) = chart_shape_format(component, "downBarColor", "downBarLine") {
                chart.set_down_bar_format(&mut format);
            }
        }
    }
    configure_chart_visual_properties(&mut chart, component);
    configure_chart_axis_crossings(&mut chart, component);
    if let Some(name) = component.props.get("name").and_then(Value::as_str) {
        chart.set_name(name);
    }
    if let Some(alt_text) = component.props.get("altText").and_then(Value::as_str) {
        chart.set_alt_text(alt_text);
    }
    if component.props.get("decorative").and_then(Value::as_bool) == Some(true) {
        chart.set_decorative(true);
    }
    if let Some(movement) = component.props.get("movement").and_then(Value::as_str) {
        let movement = match movement {
            "moveAndSize" => ObjectMovement::MoveAndSizeWithCells,
            "moveOnly" => ObjectMovement::MoveButDontSizeWithCells,
            "fixed" => ObjectMovement::DontMoveOrSizeWithCells,
            _ => unreachable!("validated Chart.movement"),
        };
        chart.set_object_movement(movement);
    }
    if let Some(title) = component.props.get("title").and_then(Value::as_str) {
        chart.title().set_name(title);
    }
    if let Some(mut format) = chart_title_shape_format(component) {
        chart.title().set_format(&mut format);
    }
    if component.props.contains_key("titleFontSize")
        || component.props.contains_key("titleFontBold")
        || component.props.contains_key("titleFontItalic")
        || component.props.contains_key("titleFontColor")
        || component.props.contains_key("titleFontName")
        || component.props.contains_key("titleFontPitchFamily")
        || component.props.contains_key("titleFontCharset")
        || component.props.contains_key("titleFontUnderline")
        || component.props.contains_key("titleFontRotation")
    {
        let mut font = rust_xlsxwriter::ChartFont::new();
        if let Some(size) = component.props.get("titleFontSize").and_then(Value::as_f64) {
            font.set_size(size);
        }
        match component
            .props
            .get("titleFontBold")
            .and_then(Value::as_bool)
        {
            Some(true) => {
                font.set_bold();
            }
            Some(false) => {
                font.unset_bold();
            }
            None => {}
        }
        if component
            .props
            .get("titleFontItalic")
            .and_then(Value::as_bool)
            == Some(true)
        {
            font.set_italic();
        }
        if component
            .props
            .get("titleFontUnderline")
            .and_then(Value::as_bool)
            == Some(true)
        {
            font.set_underline();
        }
        if let Some(rotation) = component
            .props
            .get("titleFontRotation")
            .and_then(Value::as_i64)
        {
            font.set_rotation(i16::try_from(rotation).expect("validated title font rotation"));
        }
        if let Some(color) = component
            .props
            .get("titleFontColor")
            .and_then(Value::as_str)
        {
            font.set_color(color);
        }
        if let Some(name) = component.props.get("titleFontName").and_then(Value::as_str) {
            font.set_name(name);
        }
        if let Some(family) = component
            .props
            .get("titleFontPitchFamily")
            .and_then(Value::as_u64)
        {
            font.set_pitch_family(u8::try_from(family).expect("validated title font pitch family"));
        }
        if let Some(charset) = component
            .props
            .get("titleFontCharset")
            .and_then(Value::as_u64)
        {
            font.set_character_set(u8::try_from(charset).expect("validated title font charset"));
        }
        chart.title().set_font(&font);
    }
    if let Some(layout) = component.props.get("titleLayout") {
        chart.title().set_layout(&ChartLayout::new().set_offset(
            layout["x"].as_f64().expect("validated titleLayout.x"),
            layout["y"].as_f64().expect("validated titleLayout.y"),
        ));
    }
    if component.props.get("titleOverlay").and_then(Value::as_bool) == Some(true) {
        chart.title().set_overlay(true);
    }
    if component
        .props
        .get("autoTitleDeleted")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.title().set_hidden();
    }
    if let Some(title) = component.props.get("xAxisTitle").and_then(Value::as_str) {
        chart.x_axis().set_name(title);
    }
    if let Some(title) = component.props.get("yAxisTitle").and_then(Value::as_str) {
        chart.y_axis().set_name(title);
    }
    if let Some(layout) = component.props.get("xAxisTitleLayout") {
        chart
            .x_axis()
            .set_label_layout(&ChartLayout::new().set_offset(
                layout["x"].as_f64().expect("validated xAxisTitleLayout.x"),
                layout["y"].as_f64().expect("validated xAxisTitleLayout.y"),
            ));
    }
    if let Some(layout) = component.props.get("yAxisTitleLayout") {
        chart
            .y_axis()
            .set_label_layout(&ChartLayout::new().set_offset(
                layout["x"].as_f64().expect("validated yAxisTitleLayout.x"),
                layout["y"].as_f64().expect("validated yAxisTitleLayout.y"),
            ));
    }
    if let Some(format) = chart_axis_title_format(component, "x") {
        let mut format = format;
        chart.x_axis().set_name_format(&mut format);
    }
    if let Some(format) = chart_axis_title_format(component, "y") {
        let mut format = format;
        chart.y_axis().set_name_format(&mut format);
    }
    let x_axis_title_font = chart_axis_font(component, "xAxisTitleFont");
    if has_chart_axis_font(component, "xAxisTitleFont") {
        chart.x_axis().set_name_font(&x_axis_title_font);
    }
    let y_axis_title_font = chart_axis_font(component, "yAxisTitleFont");
    if has_chart_axis_font(component, "yAxisTitleFont") {
        chart.y_axis().set_name_font(&y_axis_title_font);
    }
    let x_axis_label_font = chart_axis_font(component, "xAxisLabelFont");
    if has_chart_axis_font(component, "xAxisLabelFont") {
        chart.x_axis().set_font(&x_axis_label_font);
    }
    let y_axis_label_font = chart_axis_font(component, "yAxisLabelFont");
    if has_chart_axis_font(component, "yAxisLabelFont") {
        chart.y_axis().set_font(&y_axis_label_font);
    }
    configure_chart_axis_number_formats(&mut chart, component);
    configure_chart_axis_bounds(&mut chart, component);
    configure_chart_axis_log_base(&mut chart, component);
    configure_chart_value_axis_reversed(&mut chart, component);
    configure_chart_scatter_axes_reversed(&mut chart, component);
    configure_chart_value_axis_display_units(&mut chart, component);
    configure_chart_scatter_axis_display_units(&mut chart, component);
    if component
        .props
        .get("showHiddenData")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.show_hidden_data();
    }
    if let Some(empty_cells) = component.props.get("emptyCellsAs").and_then(Value::as_str) {
        chart.show_empty_cells_as(match empty_cells {
            "gap" => ChartEmptyCells::Gaps,
            "zero" => ChartEmptyCells::Zero,
            "span" => ChartEmptyCells::Connected,
            _ => unreachable!("validated Chart.emptyCellsAs"),
        });
    }
    if component
        .props
        .get("showNaAsEmptyCell")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.show_na_as_empty_cell();
    }
    if component.props.get("dropLines").and_then(Value::as_bool) == Some(true) {
        chart.set_drop_lines(true);
        if component
            .props
            .get("dropLinesHidden")
            .and_then(Value::as_bool)
            == Some(true)
        {
            let mut line = ChartLine::new();
            line.set_hidden(true);
            if let Some(width) = component
                .props
                .get("dropLinesWidth")
                .and_then(Value::as_f64)
            {
                line.set_width(width);
            }
            chart.set_drop_lines_format(&mut line);
        } else {
            let mut format = chart_shape_format(component, "__none__", "dropLines");
            if let Some(format) = format.as_mut() {
                chart.set_drop_lines_format(format);
            }
        }
    }
    configure_chart_category_axis_settings(&mut chart, component)?;
    configure_chart_axis_units(&mut chart, component);
    configure_chart_gridlines(&mut chart, component);
    if component.props.get("showLegend").and_then(Value::as_bool) == Some(false) {
        chart.legend().set_hidden();
    }
    if let Some(position) = component
        .props
        .get("legendPosition")
        .and_then(Value::as_str)
    {
        let position = match position {
            "right" => ChartLegendPosition::Right,
            "left" => ChartLegendPosition::Left,
            "top" => ChartLegendPosition::Top,
            "bottom" => ChartLegendPosition::Bottom,
            "topRight" => ChartLegendPosition::TopRight,
            _ => unreachable!("validated Chart.legendPosition"),
        };
        chart.legend().set_position(position);
    }
    if component
        .props
        .get("legendOverlay")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.legend().set_overlay(true);
    }
    let mut explicit_legend_entries = component
        .props
        .get("legendDeletedEntries")
        .and_then(Value::as_array)
        .filter(|entries| !entries.is_empty())
        .map(|entries| {
            entries
                .iter()
                .map(|entry| {
                    usize::try_from(entry.as_u64().expect("validated legend entry index"))
                        .expect("legend entry index fits usize")
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    let has_explicit_legend_entries = !explicit_legend_entries.is_empty();
    let chart_series_count = component
        .children
        .iter()
        .filter(|child| child["type"] == "Series")
        .count();
    if let Some(width) = component.props.get("width").and_then(Value::as_u64) {
        chart.set_width(u32::try_from(width).expect("validated Chart.width"));
    }
    if let Some(height) = component.props.get("height").and_then(Value::as_u64) {
        chart.set_height(u32::try_from(height).expect("validated Chart.height"));
    }
    let mut series_legend_index = 0;
    let mut trendline_legend_index = chart_series_count;
    for child in &component.children {
        let child: Node = serde_json::from_value(child.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if child.r#type == "ChartDataTable" {
            let mut data_table = XlsxChartDataTable::new();
            if let Some(value) = child
                .props
                .get("showHorizontalBorders")
                .and_then(Value::as_bool)
            {
                data_table = data_table.show_horizontal_borders(value);
            }
            if let Some(value) = child
                .props
                .get("showVerticalBorders")
                .and_then(Value::as_bool)
            {
                data_table = data_table.show_vertical_borders(value);
            }
            if let Some(value) = child
                .props
                .get("showOutlineBorders")
                .and_then(Value::as_bool)
            {
                data_table = data_table.show_outline_borders(value);
            }
            if let Some(value) = child.props.get("showLegendKeys").and_then(Value::as_bool) {
                data_table = data_table.show_legend_keys(value);
            }
            let mut shape_format = chart_shape_format(&child, "fillColor", "line");
            if let Some(pattern) = child.props.get("fillPattern").and_then(Value::as_str) {
                let mut pattern_fill = ChartPatternFill::new();
                pattern_fill.set_pattern(chart_pattern_fill_type(pattern));
                if let Some(color) = child
                    .props
                    .get("fillForegroundColor")
                    .and_then(Value::as_str)
                {
                    pattern_fill.set_foreground_color(color);
                }
                if let Some(color) = child
                    .props
                    .get("fillBackgroundColor")
                    .and_then(Value::as_str)
                {
                    pattern_fill.set_background_color(color);
                }
                let mut format = shape_format.take().unwrap_or_default();
                format.set_pattern_fill(&pattern_fill);
                shape_format = Some(format);
            }
            if child
                .props
                .get("fillHidden")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            {
                let mut format = shape_format.take().unwrap_or_default();
                format.set_no_fill();
                shape_format = Some(format);
            }
            if let Some(mut format) = shape_format {
                data_table = data_table.set_format(&mut format);
            }
            if [
                "fontSize",
                "fontBold",
                "fontItalic",
                "fontUnderline",
                "fontColor",
                "fontName",
                "fontPitchFamily",
                "fontCharset",
                "fontRotation",
                "fontRightToLeft",
            ]
            .iter()
            .any(|property| child.props.contains_key(*property))
            {
                let mut font = rust_xlsxwriter::ChartFont::new();
                if let Some(size) = child.props.get("fontSize").and_then(Value::as_f64) {
                    font.set_size(size);
                }
                match child.props.get("fontBold").and_then(Value::as_bool) {
                    Some(true) => {
                        font.set_bold();
                    }
                    Some(false) => {
                        font.unset_bold();
                    }
                    None => {}
                }
                if child.props.get("fontItalic").and_then(Value::as_bool) == Some(true) {
                    font.set_italic();
                }
                if child.props.get("fontUnderline").and_then(Value::as_bool) == Some(true) {
                    font.set_underline();
                }
                if let Some(color) = child.props.get("fontColor").and_then(Value::as_str) {
                    font.set_color(color);
                }
                if let Some(name) = child.props.get("fontName").and_then(Value::as_str) {
                    font.set_name(name);
                }
                if let Some(pitch_family) =
                    child.props.get("fontPitchFamily").and_then(Value::as_u64)
                {
                    font.set_pitch_family(
                        u8::try_from(pitch_family).expect("validated pitch family"),
                    );
                }
                if let Some(charset) = child.props.get("fontCharset").and_then(Value::as_u64) {
                    font.set_character_set(u8::try_from(charset).expect("validated font charset"));
                }
                if let Some(rotation) = child.props.get("fontRotation").and_then(Value::as_i64) {
                    font.set_rotation(i16::try_from(rotation).expect("validated font rotation"));
                }
                if let Some(right_to_left) =
                    child.props.get("fontRightToLeft").and_then(Value::as_bool)
                {
                    font.set_right_to_left(right_to_left);
                }
                data_table = data_table.set_font(&font);
            }
            chart.set_data_table(&data_table);
        }
    }
    for child in &component.children {
        let series: Node = serde_json::from_value(child.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if series.r#type == "ChartDataTable" {
            continue;
        }
        let chart_series = chart.add_series();
        chart_series.set_values(
            series.props["values"]
                .as_str()
                .expect("validated Series.values"),
        );
        if let Some(categories) = series.props.get("categories").and_then(Value::as_str) {
            chart_series.set_categories(categories);
        }
        if let Some(name) = series.props.get("name").and_then(Value::as_str) {
            chart_series.set_name(name);
        }
        if let Some(title) = series.props.get("title").and_then(Value::as_str) {
            chart_series.set_name(title);
        }
        if series.props.get("secondaryAxis").and_then(Value::as_bool) == Some(true) {
            chart_series.set_secondary_axis(true);
        }
        if series
            .props
            .get("deleteFromLegend")
            .and_then(Value::as_bool)
            == Some(true)
        {
            chart_series.delete_from_legend(true);
            if has_explicit_legend_entries {
                explicit_legend_entries.push(series_legend_index);
            }
        }
        series_legend_index += 1;
        let has_trendline = series
            .children
            .iter()
            .any(|child| child["type"] == "Trendline");
        let trendline_is_deleted = series
            .children
            .iter()
            .find(|child| child["type"] == "Trendline")
            .is_some_and(|child| child["props"]["deleteFromLegend"].as_bool() == Some(true));
        if trendline_is_deleted && has_explicit_legend_entries {
            explicit_legend_entries.push(trendline_legend_index);
        }
        if has_trendline {
            trendline_legend_index += 1;
        }
        configure_chart_series_data_labels(chart_series, &series);
        configure_chart_series_marker(chart_series, &series);
        configure_chart_series_line(chart_series, &series);
        configure_chart_series_point_colors(chart_series, &series);
        configure_chart_series_spacing(chart_series, &series);
        if let Some(smooth) = series.props.get("smooth").and_then(Value::as_bool) {
            chart_series.set_smooth(smooth);
        }
        if series
            .props
            .get("invertIfNegative")
            .and_then(Value::as_bool)
            == Some(true)
        {
            chart_series.set_invert_if_negative();
        }
        configure_chart_series_trendline(chart_series, &series);
        configure_chart_series_error_bars(chart_series, &series)?;
        if component.props.get("type").and_then(Value::as_str) == Some("stock") {
            chart_series
                .set_format(ChartLine::new().set_hidden(true))
                .set_marker(ChartMarker::new().set_none());
        }
    }
    if has_explicit_legend_entries {
        explicit_legend_entries.sort_unstable();
        explicit_legend_entries.dedup();
        chart.legend().delete_entries(&explicit_legend_entries);
    }
    worksheet
        .insert_chart(row, column, &chart)
        .map(|_| ())
        .map_err(|error| Error::Compile(format!("cannot insert Chart at {cell}: {error}")))
}

fn chart_axis_font(component: &Node, prefix: &str) -> ChartFont {
    let property = |suffix: &str| format!("{prefix}{suffix}");
    let mut font = ChartFont::new();
    if let Some(size) = component
        .props
        .get(&property("Size"))
        .and_then(Value::as_f64)
    {
        font.set_size(size);
    }
    if component
        .props
        .get(&property("Bold"))
        .and_then(Value::as_bool)
        == Some(true)
    {
        font.set_bold();
    } else if component
        .props
        .get(&property("Bold"))
        .and_then(Value::as_bool)
        == Some(false)
    {
        font.unset_bold();
    }
    if component
        .props
        .get(&property("Italic"))
        .and_then(Value::as_bool)
        == Some(true)
    {
        font.set_italic();
    }
    if component
        .props
        .get(&property("Underline"))
        .and_then(Value::as_bool)
        == Some(true)
    {
        font.set_underline();
    }
    if let Some(color) = component
        .props
        .get(&property("Color"))
        .and_then(Value::as_str)
    {
        font.set_color(color);
    }
    if let Some(name) = component
        .props
        .get(&property("Name"))
        .and_then(Value::as_str)
    {
        font.set_name(name);
    }
    if let Some(family) = component
        .props
        .get(&property("PitchFamily"))
        .and_then(Value::as_u64)
    {
        font.set_pitch_family(u8::try_from(family).expect("validated axis font pitch family"));
    }
    if let Some(charset) = component
        .props
        .get(&property("Charset"))
        .and_then(Value::as_u64)
    {
        font.set_character_set(u8::try_from(charset).expect("validated axis font charset"));
    }
    if let Some(rotation) = component
        .props
        .get(&property("Rotation"))
        .and_then(Value::as_i64)
    {
        font.set_rotation(i16::try_from(rotation).expect("validated axis font rotation"));
    }
    font
}

fn chart_has_legend_font(component: &Node) -> bool {
    [
        "Size",
        "Bold",
        "Italic",
        "Underline",
        "Color",
        "Name",
        "PitchFamily",
        "Charset",
        "Rotation",
    ]
    .iter()
    .any(|suffix| component.props.contains_key(&format!("legendFont{suffix}")))
}

fn configure_chart_legend_font(chart: &mut Chart, component: &Node) {
    if chart_has_legend_font(component) {
        let font = chart_axis_font(component, "legendFont");
        chart.legend().set_font(&font);
    }
}

fn has_chart_axis_font(component: &Node, prefix: &str) -> bool {
    [
        "Size",
        "Bold",
        "Italic",
        "Underline",
        "Color",
        "Name",
        "PitchFamily",
        "Charset",
        "Rotation",
    ]
    .iter()
    .any(|suffix| component.props.contains_key(&format!("{prefix}{suffix}")))
}

fn configure_chart_series_spacing(chart_series: &mut rust_xlsxwriter::ChartSeries, series: &Node) {
    if let Some(gap) = series.props.get("gap").and_then(Value::as_u64) {
        chart_series.set_gap(u16::try_from(gap).expect("validated Series.gap range"));
    }
    if let Some(overlap) = series.props.get("overlap").and_then(Value::as_i64) {
        chart_series.set_overlap(i8::try_from(overlap).expect("validated Series.overlap range"));
    }
}

fn configure_chart_series_point_colors(
    chart_series: &mut rust_xlsxwriter::ChartSeries,
    series: &Node,
) {
    let Some(colors) = series.props.get("pointColors").and_then(Value::as_object) else {
        return;
    };
    let Some(max_index) = colors
        .keys()
        .filter_map(|key| key.parse::<usize>().ok())
        .max()
    else {
        return;
    };
    let mut points = vec![ChartPoint::new(); max_index + 1];
    let transparencies = series
        .props
        .get("pointColorTransparencies")
        .and_then(Value::as_object);
    for (index, color) in colors {
        let index = index.parse::<usize>().expect("validated point color index");
        let color = color.as_str().expect("validated point color");
        let mut fill = ChartSolidFill::new();
        fill.set_color(color);
        if let Some(transparency) = transparencies
            .and_then(|values| values.get(&index.to_string()))
            .and_then(Value::as_u64)
        {
            fill.set_transparency(
                u8::try_from(transparency).expect("validated point color transparency"),
            );
        }
        let mut format = ChartFormat::new();
        format.set_solid_fill(&fill);
        points[index] = ChartPoint::new().set_format(&mut format);
    }
    chart_series.set_points(&points);
}

fn configure_chart_series_line(chart_series: &mut rust_xlsxwriter::ChartSeries, series: &Node) {
    if ![
        "lineColor",
        "lineWidth",
        "lineDash",
        "lineTransparency",
        "lineHidden",
    ]
    .iter()
    .any(|key| series.props.contains_key(*key))
    {
        return;
    }
    let mut line = ChartLine::new();
    if let Some(color) = series.props.get("lineColor").and_then(Value::as_str) {
        line.set_color(color);
    }
    if let Some(width) = series.props.get("lineWidth").and_then(Value::as_f64) {
        line.set_width(width);
    }
    if let Some(dash) = series.props.get("lineDash").and_then(Value::as_str) {
        line.set_dash_type(match dash {
            "solid" => rust_xlsxwriter::ChartLineDashType::Solid,
            "roundDot" => rust_xlsxwriter::ChartLineDashType::RoundDot,
            "squareDot" => rust_xlsxwriter::ChartLineDashType::SquareDot,
            "dash" => rust_xlsxwriter::ChartLineDashType::Dash,
            "dashDot" => rust_xlsxwriter::ChartLineDashType::DashDot,
            "longDash" => rust_xlsxwriter::ChartLineDashType::LongDash,
            "longDashDot" => rust_xlsxwriter::ChartLineDashType::LongDashDot,
            "longDashDotDot" => rust_xlsxwriter::ChartLineDashType::LongDashDotDot,
            _ => unreachable!("validated Series.lineDash"),
        });
    }
    if let Some(transparency) = series.props.get("lineTransparency").and_then(Value::as_u64) {
        line.set_transparency(u8::try_from(transparency).expect("validated transparency"));
    }
    if let Some(hidden) = series.props.get("lineHidden").and_then(Value::as_bool) {
        line.set_hidden(hidden);
    }
    chart_series.set_format(&mut line);
}

fn configure_chart_series_marker(chart_series: &mut rust_xlsxwriter::ChartSeries, series: &Node) {
    if ![
        "markerType",
        "markerSize",
        "markerFillColor",
        "markerFillTransparency",
        "markerLineColor",
        "markerLineWidth",
        "markerLineDash",
        "markerLineTransparency",
        "markerLineHidden",
    ]
    .iter()
    .any(|property| series.props.contains_key(*property))
    {
        return;
    }
    let mut marker = ChartMarker::new();
    if let Some(marker_type) = series.props.get("markerType").and_then(Value::as_str) {
        if marker_type == "none" {
            marker.set_none();
        } else if marker_type == "automatic" {
            marker.set_automatic();
        } else {
            let marker_type = match marker_type {
                "automatic" => unreachable!("automatic marker is handled above"),
                "square" => ChartMarkerType::Square,
                "diamond" => ChartMarkerType::Diamond,
                "triangle" => ChartMarkerType::Triangle,
                "x" => ChartMarkerType::X,
                "star" => ChartMarkerType::Star,
                "shortDash" => ChartMarkerType::ShortDash,
                "longDash" => ChartMarkerType::LongDash,
                "circle" => ChartMarkerType::Circle,
                "plusSign" => ChartMarkerType::PlusSign,
                _ => unreachable!("validated Series.markerType"),
            };
            marker.set_type(marker_type);
        }
    }
    if let Some(size) = series.props.get("markerSize").and_then(Value::as_u64) {
        marker.set_size(u8::try_from(size).expect("validated Series.markerSize"));
    }
    if let Some(mut format) = chart_marker_format(series) {
        marker.set_format(&mut format);
    }
    chart_series.set_marker(&marker);
}

fn chart_marker_format(series: &Node) -> Option<ChartFormat> {
    let mut format = ChartFormat::new();
    let mut has_format = false;
    if let Some(color) = series.props.get("markerFillColor").and_then(Value::as_str) {
        let mut fill = ChartSolidFill::new();
        fill.set_color(color);
        if let Some(transparency) = series
            .props
            .get("markerFillTransparency")
            .and_then(Value::as_u64)
        {
            fill.set_transparency(
                u8::try_from(transparency).expect("validated Series.markerFillTransparency"),
            );
        }
        format.set_solid_fill(&fill);
        has_format = true;
    }
    let has_line = [
        "markerLineColor",
        "markerLineWidth",
        "markerLineDash",
        "markerLineTransparency",
        "markerLineHidden",
    ]
    .iter()
    .any(|property| series.props.contains_key(*property));
    if has_line {
        let mut line = ChartLine::new();
        if let Some(color) = series.props.get("markerLineColor").and_then(Value::as_str) {
            line.set_color(color);
        }
        if let Some(width) = series.props.get("markerLineWidth").and_then(Value::as_f64) {
            line.set_width(width);
        }
        if let Some(dash) = series.props.get("markerLineDash").and_then(Value::as_str) {
            line.set_dash_type(chart_line_dash_type(dash));
        }
        if let Some(transparency) = series
            .props
            .get("markerLineTransparency")
            .and_then(Value::as_u64)
        {
            line.set_transparency(
                u8::try_from(transparency).expect("validated markerLineTransparency"),
            );
        }
        if let Some(hidden) = series
            .props
            .get("markerLineHidden")
            .and_then(Value::as_bool)
        {
            line.set_hidden(hidden);
        }
        format.set_line(&line);
        has_format = true;
    }
    if has_format { Some(format) } else { None }
}

fn configure_chart_series_error_bars(
    chart_series: &mut rust_xlsxwriter::ChartSeries,
    series: &Node,
) -> xlsx_jsx::Result<()> {
    for child in &series.children {
        let error_bars: Node = serde_json::from_value(child.clone())
            .map_err(|error| Error::Compile(error.to_string()))?;
        if error_bars.r#type == "Trendline" {
            continue;
        }
        let axis = error_bars.props["axis"].as_str().expect("validated axis");
        let error_type = error_bars.props["type"].as_str().expect("validated type");
        let value = error_bars.props.get("value").and_then(Value::as_f64);
        let mut settings = ChartErrorBars::new();
        let error_type = match error_type {
            "standardError" => ChartErrorBarsType::StandardError,
            "fixedValue" => ChartErrorBarsType::FixedValue(value.expect("validated value")),
            "percentage" => ChartErrorBarsType::Percentage(value.expect("validated value")),
            "standardDeviation" => {
                ChartErrorBarsType::StandardDeviation(value.expect("validated value"))
            }
            "custom" => ChartErrorBarsType::Custom(
                rust_xlsxwriter::ChartRange::new_from_string(
                    error_bars.props["plusRange"]
                        .as_str()
                        .expect("validated plusRange"),
                ),
                rust_xlsxwriter::ChartRange::new_from_string(
                    error_bars.props["minusRange"]
                        .as_str()
                        .expect("validated minusRange"),
                ),
            ),
            _ => unreachable!("validated error-bar type"),
        };
        settings.set_type(error_type);
        if let Some(direction) = error_bars.props.get("direction").and_then(Value::as_str) {
            settings.set_direction(match direction {
                "both" => ChartErrorBarsDirection::Both,
                "minus" => ChartErrorBarsDirection::Minus,
                "plus" => ChartErrorBarsDirection::Plus,
                _ => unreachable!("validated error-bar direction"),
            });
        }
        if error_bars.props.get("endCap").and_then(Value::as_bool) == Some(false) {
            settings.set_end_cap(false);
        }
        if ["lineColor", "lineWidth", "lineDash", "lineTransparency"]
            .iter()
            .any(|key| error_bars.props.contains_key(*key))
        {
            let mut line = ChartLine::new();
            if let Some(color) = error_bars.props.get("lineColor").and_then(Value::as_str) {
                line.set_color(color);
            }
            if let Some(width) = error_bars.props.get("lineWidth").and_then(Value::as_f64) {
                line.set_width(width);
            }
            if let Some(dash) = error_bars.props.get("lineDash").and_then(Value::as_str) {
                line.set_dash_type(chart_line_dash_type(dash));
            }
            if let Some(transparency) = error_bars
                .props
                .get("lineTransparency")
                .and_then(Value::as_u64)
            {
                line.set_transparency(
                    u8::try_from(transparency).expect("validated ErrorBars.lineTransparency"),
                );
            }
            settings.set_format(&mut line);
        }
        match axis {
            "x" => {
                chart_series.set_x_error_bars(&settings);
            }
            "y" => {
                chart_series.set_y_error_bars(&settings);
            }
            _ => unreachable!("validated error-bar axis"),
        }
    }
    Ok(())
}

#[expect(
    clippy::too_many_lines,
    reason = "Trendline settings are applied together to preserve the writer's one-object configuration contract."
)]
fn configure_chart_series_trendline(
    chart_series: &mut rust_xlsxwriter::ChartSeries,
    series: &Node,
) {
    let Some(child) = series
        .children
        .iter()
        .find(|child| child["type"] == "Trendline")
    else {
        return;
    };
    let trendline: Node = serde_json::from_value(child.clone()).expect("validated Trendline node");
    let mut settings = ChartTrendline::new();
    let trend_type = trendline.props["type"]
        .as_str()
        .expect("validated Trendline.type");
    let kind = match trend_type {
        "linear" => ChartTrendlineType::Linear,
        "exponential" => ChartTrendlineType::Exponential,
        "logarithmic" => ChartTrendlineType::Logarithmic,
        "polynomial" => ChartTrendlineType::Polynomial(
            u8::try_from(trendline.props["order"].as_u64().expect("validated order"))
                .expect("order fits u8"),
        ),
        "power" => ChartTrendlineType::Power,
        "movingAverage" => ChartTrendlineType::MovingAverage(
            u8::try_from(
                trendline.props["period"]
                    .as_u64()
                    .expect("validated period"),
            )
            .expect("period fits u8"),
        ),
        _ => unreachable!("validated Trendline.type"),
    };
    settings.set_type(kind);
    if let Some(name) = trendline.props.get("name").and_then(Value::as_str) {
        settings.set_name(name);
    }
    if [
        "labelFontSize",
        "labelFontBold",
        "labelFontItalic",
        "labelFontUnderline",
        "labelFontColor",
        "labelFontName",
    ]
    .iter()
    .any(|property| trendline.props.contains_key(*property))
    {
        let mut font = rust_xlsxwriter::ChartFont::new();
        if let Some(size) = trendline.props.get("labelFontSize").and_then(Value::as_f64) {
            font.set_size(size);
        }
        match trendline
            .props
            .get("labelFontBold")
            .and_then(Value::as_bool)
        {
            Some(true) => {
                font.set_bold();
            }
            Some(false) => {
                font.unset_bold();
            }
            None => {}
        }
        if trendline
            .props
            .get("labelFontItalic")
            .and_then(Value::as_bool)
            == Some(true)
        {
            font.set_italic();
        }
        if trendline
            .props
            .get("labelFontUnderline")
            .and_then(Value::as_bool)
            == Some(true)
        {
            font.set_underline();
        }
        if let Some(color) = trendline
            .props
            .get("labelFontColor")
            .and_then(Value::as_str)
        {
            font.set_color(color);
        }
        if let Some(name) = trendline.props.get("labelFontName").and_then(Value::as_str) {
            font.set_name(name);
        }
        settings.set_label_font(&font);
    }
    if let Some(forward) = trendline.props.get("forward").and_then(Value::as_f64) {
        settings.set_forward_period(forward);
    }
    if let Some(backward) = trendline.props.get("backward").and_then(Value::as_f64) {
        settings.set_backward_period(backward);
    }
    if let Some(intercept) = trendline.props.get("intercept").and_then(Value::as_f64) {
        settings.set_intercept(intercept);
    }
    if trendline
        .props
        .get("deleteFromLegend")
        .and_then(Value::as_bool)
        == Some(true)
    {
        settings.delete_from_legend(true);
    }
    if trendline
        .props
        .get("displayEquation")
        .and_then(Value::as_bool)
        == Some(true)
    {
        settings.display_equation(true);
    }
    if trendline
        .props
        .get("displayRSquared")
        .and_then(Value::as_bool)
        == Some(true)
    {
        settings.display_r_squared(true);
    }
    if let Some(mut format) = chart_shape_format(&trendline, "labelFillColor", "labelLine") {
        settings.set_label_format(&mut format);
    }
    if [
        "lineColor",
        "lineWidth",
        "lineDash",
        "lineTransparency",
        "lineHidden",
    ]
    .iter()
    .any(|property| trendline.props.contains_key(*property))
    {
        let mut line = ChartLine::new();
        if let Some(color) = trendline.props.get("lineColor").and_then(Value::as_str) {
            line.set_color(color);
        }
        if let Some(width) = trendline.props.get("lineWidth").and_then(Value::as_f64) {
            line.set_width(width);
        }
        if let Some(dash) = trendline.props.get("lineDash").and_then(Value::as_str) {
            line.set_dash_type(chart_line_dash_type(dash));
        }
        if let Some(transparency) = trendline
            .props
            .get("lineTransparency")
            .and_then(Value::as_u64)
        {
            line.set_transparency(
                u8::try_from(transparency).expect("validated Trendline.lineTransparency"),
            );
        }
        if let Some(hidden) = trendline.props.get("lineHidden").and_then(Value::as_bool) {
            line.set_hidden(hidden);
        }
        settings.set_format(&mut line);
    }
    chart_series.set_trendline(&settings);
}

fn configure_chart_series_data_labels(
    chart_series: &mut rust_xlsxwriter::ChartSeries,
    series: &Node,
) {
    if let Some(labels) = compile_custom_chart_data_labels(series) {
        chart_series.set_custom_data_labels(&labels);
    }
    if let Some(data_label) = compile_series_chart_data_label(series) {
        chart_series.set_data_label(&data_label);
    }
}

fn compile_custom_chart_data_labels(series: &Node) -> Option<Vec<ChartDataLabel>> {
    series
        .props
        .get("customLabels")
        .and_then(Value::as_array)
        .map(|labels| {
            labels
                .iter()
                .map(|label| {
                    label.as_str().map_or_else(ChartDataLabel::default, |text| {
                        ChartDataLabel::new().set_value(text).to_custom()
                    })
                })
                .collect()
        })
}

fn compile_series_chart_data_label(series: &Node) -> Option<ChartDataLabel> {
    let show_value = ["showValue", "showYValue"]
        .iter()
        .any(|property| series.props.get(*property).and_then(Value::as_bool) == Some(true));
    let show_category_name = ["showCategoryName", "showXValue"]
        .iter()
        .any(|property| series.props.get(*property).and_then(Value::as_bool) == Some(true));
    let show_series_name =
        series.props.get("showSeriesName").and_then(Value::as_bool) == Some(true);
    let show_percentage = series.props.get("showPercentage").and_then(Value::as_bool) == Some(true);
    let show_legend_key = series.props.get("showLegendKey").and_then(Value::as_bool) == Some(true);
    let show_leader_lines =
        series.props.get("showLeaderLines").and_then(Value::as_bool) == Some(true);
    let position = series
        .props
        .get("labelPosition")
        .and_then(Value::as_str)
        .and_then(chart_data_label_position);
    let separator = series
        .props
        .get("labelSeparator")
        .and_then(Value::as_str)
        .and_then(chart_data_label_separator_value);
    let number_format = series
        .props
        .get("labelNumberFormat")
        .and_then(Value::as_str);
    let has_font = [
        "labelFontSize",
        "labelFontBold",
        "labelFontItalic",
        "labelFontUnderline",
        "labelFontColor",
        "labelFontName",
        "labelFontPitchFamily",
        "labelFontCharset",
        "labelFontRotation",
    ]
    .iter()
    .any(|property| series.props.contains_key(*property));
    let has_shape = [
        "labelFillColor",
        "labelLineColor",
        "labelLineWidth",
        "labelLineDash",
        "labelLineTransparency",
    ]
    .iter()
    .any(|property| series.props.contains_key(*property))
        || series.props.get("labelLineHidden").and_then(Value::as_bool) == Some(true);
    if !(show_value
        || show_category_name
        || show_series_name
        || show_percentage
        || show_legend_key
        || show_leader_lines
        || position.is_some())
        && separator.is_none()
        && number_format.is_none()
        && !has_font
        && !has_shape
    {
        return None;
    }
    let mut data_label = ChartDataLabel::new();
    if show_value {
        data_label.show_value();
    }
    if show_category_name {
        data_label.show_category_name();
    }
    if show_series_name {
        data_label.show_series_name();
    }
    if show_percentage {
        data_label.show_percentage();
    }
    if let Some(position) = position {
        data_label.set_position(position);
    }
    if show_legend_key {
        data_label.show_legend_key();
    }
    if show_leader_lines {
        data_label.show_leader_lines();
    }
    if let Some(separator) = separator {
        data_label.set_separator(separator);
    }
    if let Some(number_format) = number_format {
        data_label.set_num_format(number_format);
    }
    if has_font {
        configure_chart_data_label_font(&mut data_label, series);
    }
    if let Some(mut format) = chart_shape_format(series, "labelFillColor", "labelLine") {
        data_label.set_format(&mut format);
    }
    Some(data_label)
}

fn configure_chart_data_label_font(data_label: &mut ChartDataLabel, series: &Node) {
    let mut font = rust_xlsxwriter::ChartFont::new();
    if let Some(size) = series.props.get("labelFontSize").and_then(Value::as_f64) {
        font.set_size(size);
    }
    match series.props.get("labelFontBold").and_then(Value::as_bool) {
        Some(true) => {
            font.set_bold();
        }
        Some(false) => {
            font.unset_bold();
        }
        None => {}
    }
    if series.props.get("labelFontItalic").and_then(Value::as_bool) == Some(true) {
        font.set_italic();
    }
    if series
        .props
        .get("labelFontUnderline")
        .and_then(Value::as_bool)
        == Some(true)
    {
        font.set_underline();
    }
    if let Some(color) = series.props.get("labelFontColor").and_then(Value::as_str) {
        font.set_color(color);
    }
    if let Some(name) = series.props.get("labelFontName").and_then(Value::as_str) {
        font.set_name(name);
    }
    if let Some(family) = series
        .props
        .get("labelFontPitchFamily")
        .and_then(Value::as_u64)
    {
        font.set_pitch_family(u8::try_from(family).expect("validated label font pitch family"));
    }
    if let Some(charset) = series.props.get("labelFontCharset").and_then(Value::as_u64) {
        font.set_character_set(u8::try_from(charset).expect("validated label font charset"));
    }
    if let Some(rotation) = series
        .props
        .get("labelFontRotation")
        .and_then(Value::as_i64)
    {
        font.set_rotation(i16::try_from(rotation).expect("validated label font rotation"));
    }
    data_label.set_font(&font);
}

fn chart_data_label_position(position: &str) -> Option<ChartDataLabelPosition> {
    match position {
        "center" => Some(ChartDataLabelPosition::Center),
        "right" => Some(ChartDataLabelPosition::Right),
        "left" => Some(ChartDataLabelPosition::Left),
        "above" => Some(ChartDataLabelPosition::Above),
        "below" => Some(ChartDataLabelPosition::Below),
        "insideBase" => Some(ChartDataLabelPosition::InsideBase),
        "insideEnd" => Some(ChartDataLabelPosition::InsideEnd),
        "outsideEnd" => Some(ChartDataLabelPosition::OutsideEnd),
        "bestFit" => Some(ChartDataLabelPosition::BestFit),
        _ => None,
    }
}

fn configure_chart_axis_number_formats(chart: &mut Chart, component: &Node) {
    if let Some(format) = component
        .props
        .get("xAxisNumberFormat")
        .and_then(Value::as_str)
    {
        chart.x_axis().set_num_format(format);
    }
    if let Some(format) = component
        .props
        .get("yAxisNumberFormat")
        .and_then(Value::as_str)
    {
        chart.y_axis().set_num_format(format);
    }
}

fn configure_chart_axis_bounds(chart: &mut Chart, component: &Node) {
    if let Some(minimum) = component.props.get("xAxisMin").and_then(Value::as_f64) {
        chart.x_axis().set_min(minimum);
    }
    if let Some(maximum) = component.props.get("xAxisMax").and_then(Value::as_f64) {
        chart.x_axis().set_max(maximum);
    }
    let value_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.x_axis()
    } else {
        chart.y_axis()
    };
    if let Some(minimum) = component.props.get("yAxisMin").and_then(Value::as_f64) {
        value_axis.set_min(minimum);
    }
    if let Some(maximum) = component.props.get("yAxisMax").and_then(Value::as_f64) {
        value_axis.set_max(maximum);
    }
}

fn configure_chart_axis_log_base(chart: &mut Chart, component: &Node) {
    if let Some(base) = component.props.get("xAxisLogBase").and_then(Value::as_u64) {
        chart
            .x_axis()
            .set_log_base(u16::try_from(base).expect("validated Chart.xAxisLogBase"));
    }
    let Some(base) = component.props.get("yAxisLogBase").and_then(Value::as_u64) else {
        return;
    };
    let value_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.x_axis()
    } else {
        chart.y_axis()
    };
    value_axis.set_log_base(u16::try_from(base).expect("validated Chart.yAxisLogBase"));
}

fn configure_chart_value_axis_display_units(chart: &mut Chart, component: &Node) {
    let Some(unit) = component
        .props
        .get("valueAxisDisplayUnit")
        .and_then(Value::as_str)
    else {
        return;
    };
    let unit = chart_axis_display_unit_type(unit);
    let value_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.x_axis()
    } else {
        chart.y_axis()
    };
    value_axis.set_display_unit_type(unit);
    if component
        .props
        .get("valueAxisDisplayUnitLabel")
        .and_then(Value::as_bool)
        == Some(false)
    {
        value_axis.set_display_units_visible(false);
    }
}

fn configure_chart_scatter_axis_display_units(chart: &mut Chart, component: &Node) {
    for (unit_property, label_property, horizontal_axis) in [
        ("xAxisDisplayUnit", "xAxisDisplayUnitLabel", true),
        ("yAxisDisplayUnit", "yAxisDisplayUnitLabel", false),
    ] {
        let Some(unit) = component.props.get(unit_property).and_then(Value::as_str) else {
            continue;
        };
        let unit = chart_axis_display_unit_type(unit);
        let axis = if horizontal_axis {
            chart.x_axis()
        } else {
            chart.y_axis()
        };
        axis.set_display_unit_type(unit);
        if component.props.get(label_property).and_then(Value::as_bool) == Some(false) {
            axis.set_display_units_visible(false);
        }
    }
}

fn chart_axis_display_unit_type(value: &str) -> ChartAxisDisplayUnitType {
    match value {
        "hundreds" => ChartAxisDisplayUnitType::Hundreds,
        "thousands" => ChartAxisDisplayUnitType::Thousands,
        "tenThousands" => ChartAxisDisplayUnitType::TenThousands,
        "hundredThousands" => ChartAxisDisplayUnitType::HundredThousands,
        "millions" => ChartAxisDisplayUnitType::Millions,
        "tenMillions" => ChartAxisDisplayUnitType::TenMillions,
        "hundredMillions" => ChartAxisDisplayUnitType::HundredMillions,
        "billions" => ChartAxisDisplayUnitType::Billions,
        "trillions" => ChartAxisDisplayUnitType::Trillions,
        _ => unreachable!("chart display unit was validated"),
    }
}

fn configure_chart_value_axis_reversed(chart: &mut Chart, component: &Node) {
    if component
        .props
        .get("valueAxisReversed")
        .and_then(Value::as_bool)
        != Some(true)
    {
        return;
    }
    let value_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.x_axis()
    } else {
        chart.y_axis()
    };
    value_axis.set_reverse();
}

fn configure_chart_scatter_axes_reversed(chart: &mut Chart, component: &Node) {
    if component
        .props
        .get("xAxisReversed")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.x_axis().set_reverse();
    }
    if component
        .props
        .get("yAxisReversed")
        .and_then(Value::as_bool)
        == Some(true)
    {
        chart.y_axis().set_reverse();
    }
}

fn configure_chart_category_axis_intervals(chart: &mut Chart, component: &Node) {
    let category_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.y_axis()
    } else {
        chart.x_axis()
    };
    if let Some(interval) = component
        .props
        .get("categoryAxisLabelInterval")
        .and_then(Value::as_u64)
    {
        category_axis.set_label_interval(
            u16::try_from(interval).expect("validated category label interval"),
        );
    }
    if let Some(interval) = component
        .props
        .get("categoryAxisTickInterval")
        .and_then(Value::as_u64)
    {
        category_axis
            .set_tick_interval(u16::try_from(interval).expect("validated category tick interval"));
    }
}

fn configure_chart_axis_tick_types(chart: &mut Chart, component: &Node) -> xlsx_jsx::Result<()> {
    for (property, horizontal, major) in [
        ("horizontalAxisMajorTickType", true, true),
        ("horizontalAxisMinorTickType", true, false),
        ("verticalAxisMajorTickType", false, true),
        ("verticalAxisMinorTickType", false, false),
    ] {
        let Some(value) = component.props.get(property).and_then(Value::as_str) else {
            continue;
        };
        let tick_type = match value {
            "cross" => ChartAxisTickType::Cross,
            "inside" => ChartAxisTickType::Inside,
            "outside" => ChartAxisTickType::Outside,
            "none" => ChartAxisTickType::None,
            _ => {
                return Err(Error::Compile(format!(
                    "Chart.{property} must be cross, inside, outside, or none; choose one of these tick types"
                )));
            }
        };
        let axis = if horizontal {
            chart.x_axis()
        } else {
            chart.y_axis()
        };
        if major {
            axis.set_major_tick_type(tick_type);
        } else {
            axis.set_minor_tick_type(tick_type);
        }
    }
    Ok(())
}

fn configure_chart_category_axis_settings(
    chart: &mut Chart,
    component: &Node,
) -> xlsx_jsx::Result<()> {
    let is_bar = component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"));
    configure_chart_category_axis_intervals(chart, component);
    configure_chart_axis_tick_types(chart, component)?;
    configure_chart_axis_label_positions(chart, component)?;
    configure_chart_category_axis_label_alignment(chart, component)?;
    if component
        .props
        .get("categoryAxisType")
        .and_then(Value::as_str)
        == Some("date")
    {
        // rust_xlsxwriter selects date-axis serialization from X, but swaps
        // the unit-bearing axis data for bars before writing the plot area.
        configure_chart_date_axis(chart, component, is_bar)?;
    }
    if component
        .props
        .get("categoryAxisOnTickMarks")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        if is_bar {
            chart.y_axis().set_position_between_ticks(false);
        } else {
            chart.x_axis().set_position_between_ticks(false);
        }
    }
    configure_chart_axis_hidden(chart, component);
    Ok(())
}

fn configure_chart_date_axis(
    chart: &mut Chart,
    component: &Node,
    is_bar: bool,
) -> xlsx_jsx::Result<()> {
    chart.x_axis().set_date_axis(true);
    if is_bar {
        // rust_xlsxwriter serializes bounds from the swapped Y-axis value object
        // while deciding whether to emit dateAx from the logical X-axis.
        chart.y_axis().set_date_axis(true);
    }
    let axis = if is_bar {
        chart.y_axis()
    } else {
        chart.x_axis()
    };
    if let Some(unit) = component
        .props
        .get("categoryAxisMajorTimeUnit")
        .and_then(Value::as_str)
    {
        axis.set_major_unit_date_type(parse_chart_date_unit(unit));
    }
    if let Some(unit) = component
        .props
        .get("categoryAxisMinorTimeUnit")
        .and_then(Value::as_str)
    {
        axis.set_minor_unit_date_type(parse_chart_date_unit(unit));
    }
    for (property, is_minimum) in [
        ("categoryAxisMinDate", true),
        ("categoryAxisMaxDate", false),
    ] {
        let Some(value) = component.props.get(property).and_then(Value::as_str) else {
            continue;
        };
        let datetime = rust_xlsxwriter::ExcelDateTime::parse_from_str(value).map_err(|error| {
            Error::Compile(format!(
                "Chart.{property} `{value}` cannot be converted to an Excel date serial: {error}; use a date from 1900-01-01 through 9999-12-31"
            ))
        })?;
        if is_minimum {
            axis.set_min_date(datetime);
        } else {
            axis.set_max_date(datetime);
        }
    }
    Ok(())
}

fn parse_chart_date_unit(unit: &str) -> ChartAxisDateUnitType {
    match unit {
        "days" => ChartAxisDateUnitType::Days,
        "months" => ChartAxisDateUnitType::Months,
        "years" => ChartAxisDateUnitType::Years,
        _ => unreachable!("validated chart date unit"),
    }
}

fn configure_chart_visual_properties(chart: &mut Chart, component: &Node) {
    if let Some(style) = component.props.get("style").and_then(Value::as_u64) {
        chart.set_style(u8::try_from(style).expect("validated Chart.style"));
    }
    if let Some(hole_size) = component.props.get("holeSize").and_then(Value::as_u64) {
        chart.set_hole_size(u8::try_from(hole_size).expect("validated Chart.holeSize"));
    }
    if let Some(angle) = component
        .props
        .get("firstSliceAngle")
        .and_then(Value::as_u64)
    {
        chart.set_rotation(u16::try_from(angle).expect("validated Chart.firstSliceAngle"));
    }
}

fn configure_chart_axis_crossings(chart: &mut Chart, component: &Node) {
    let is_bar = component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"));
    for (property, horizontal_handle) in [("xAxisCrossing", true), ("yAxisCrossing", false)] {
        let Some(value) = component.props.get(property) else {
            continue;
        };
        let crossing = if let Some(value) = value.as_str() {
            match value {
                "automatic" => ChartAxisCrossing::Automatic,
                "min" => ChartAxisCrossing::Min,
                "max" => ChartAxisCrossing::Max,
                _ => unreachable!("Chart axis crossings were validated"),
            }
        } else if let Some(value) = value.as_f64() {
            let is_scatter = component
                .props
                .get("type")
                .and_then(Value::as_str)
                .is_some_and(|chart_type| chart_type.starts_with("scatter"));
            let category_handle = if is_bar {
                !horizontal_handle
            } else {
                horizontal_handle
            };
            if category_handle && !is_scatter {
                ChartAxisCrossing::CategoryNumber(
                    u32::try_from(
                        component.props[property]
                            .as_u64()
                            .expect("validated integer category crossing index"),
                    )
                    .expect("validated category crossing index"),
                )
            } else {
                ChartAxisCrossing::AxisValue(value)
            }
        } else {
            unreachable!("Chart axis crossings were validated")
        };
        let axis = if horizontal_handle {
            chart.x_axis()
        } else {
            chart.y_axis()
        };
        axis.set_crossing(crossing);
    }
}

fn configure_chart_axis_hidden(chart: &mut Chart, component: &Node) {
    for (property, horizontal) in [
        ("horizontalAxisHidden", true),
        ("verticalAxisHidden", false),
    ] {
        let Some(hidden) = component.props.get(property).and_then(Value::as_bool) else {
            continue;
        };
        let axis = if horizontal {
            chart.x_axis()
        } else {
            chart.y_axis()
        };
        axis.set_hidden(hidden);
    }
}

fn configure_chart_category_axis_label_alignment(
    chart: &mut Chart,
    component: &Node,
) -> xlsx_jsx::Result<()> {
    let Some(value) = component
        .props
        .get("categoryAxisLabelAlignment")
        .and_then(Value::as_str)
    else {
        return Ok(());
    };
    let alignment = match value {
        "center" => ChartAxisLabelAlignment::Center,
        "left" => ChartAxisLabelAlignment::Left,
        "right" => ChartAxisLabelAlignment::Right,
        _ => {
            return Err(Error::Compile(
                "Chart.categoryAxisLabelAlignment must be center, left, or right; choose one of these alignments".into(),
            ));
        }
    };
    let category_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.y_axis()
    } else {
        chart.x_axis()
    };
    category_axis.set_label_alignment(alignment);
    Ok(())
}

fn configure_chart_axis_label_positions(
    chart: &mut Chart,
    component: &Node,
) -> xlsx_jsx::Result<()> {
    for (property, horizontal) in [
        ("horizontalAxisLabelPosition", true),
        ("verticalAxisLabelPosition", false),
    ] {
        let Some(value) = component.props.get(property).and_then(Value::as_str) else {
            continue;
        };
        let position = match value {
            "nextTo" => ChartAxisLabelPosition::NextTo,
            "high" => ChartAxisLabelPosition::High,
            "low" => ChartAxisLabelPosition::Low,
            "none" => ChartAxisLabelPosition::None,
            _ => {
                return Err(Error::Compile(format!(
                    "Chart.{property} must be nextTo, high, low, or none; choose one of these label positions"
                )));
            }
        };
        let axis = if horizontal {
            chart.x_axis()
        } else {
            chart.y_axis()
        };
        axis.set_label_position(position);
    }
    Ok(())
}

fn configure_chart_axis_units(chart: &mut Chart, component: &Node) {
    if let Some(unit) = component
        .props
        .get("xAxisMajorUnit")
        .and_then(Value::as_f64)
    {
        chart.x_axis().set_major_unit(unit);
    }
    if let Some(unit) = component
        .props
        .get("xAxisMinorUnit")
        .and_then(Value::as_f64)
    {
        chart.x_axis().set_minor_unit(unit);
    }
    let value_axis = if component
        .props
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|chart_type| chart_type.starts_with("bar"))
    {
        chart.x_axis()
    } else {
        chart.y_axis()
    };
    if let Some(unit) = component
        .props
        .get("yAxisMajorUnit")
        .and_then(Value::as_f64)
    {
        value_axis.set_major_unit(unit);
    }
    if let Some(unit) = component
        .props
        .get("yAxisMinorUnit")
        .and_then(Value::as_f64)
    {
        value_axis.set_minor_unit(unit);
    }
}

fn configure_chart_gridlines(chart: &mut Chart, component: &Node) {
    for (property, axis, minor) in [
        ("horizontalAxisMajorGridlines", true, false),
        ("horizontalAxisMinorGridlines", true, true),
        ("verticalAxisMajorGridlines", false, false),
        ("verticalAxisMinorGridlines", false, true),
    ] {
        let Some(setting) = component.props.get(property) else {
            continue;
        };
        let chart_axis = if axis { chart.x_axis() } else { chart.y_axis() };
        if let Some(style) = setting.as_object() {
            let mut line = ChartLine::new();
            if let Some(color) = style.get("color").and_then(Value::as_str) {
                line.set_color(color);
            }
            if let Some(width) = style.get("width").and_then(Value::as_f64) {
                line.set_width(width);
            }
            if let Some(dash) = style.get("dash").and_then(Value::as_str) {
                line.set_dash_type(chart_line_dash_type(dash));
            }
            if let Some(transparency) = style.get("transparency").and_then(Value::as_u64) {
                line.set_transparency(
                    u8::try_from(transparency).expect("validated gridline transparency"),
                );
            }
            if minor {
                chart_axis.set_minor_gridlines_line(&line);
            } else {
                chart_axis.set_major_gridlines_line(&line);
            }
        } else {
            let visible = setting.as_bool().expect("validated gridline setting");
            if minor {
                chart_axis.set_minor_gridlines(visible);
            } else {
                chart_axis.set_major_gridlines(visible);
            }
        }
    }
}

fn chart_line_dash_type(dash: &str) -> ChartLineDashType {
    match dash {
        "solid" => ChartLineDashType::Solid,
        "roundDot" => ChartLineDashType::RoundDot,
        "squareDot" => ChartLineDashType::SquareDot,
        "dash" => ChartLineDashType::Dash,
        "dashDot" => ChartLineDashType::DashDot,
        "longDash" => ChartLineDashType::LongDash,
        "longDashDot" => ChartLineDashType::LongDashDot,
        "longDashDotDot" => ChartLineDashType::LongDashDotDot,
        _ => unreachable!("validated chart line dash"),
    }
}

